RemediationCommand:
$tempFile = "$env:TEMP\secpol_temp.cfg"
SecEdit.exe /export /cfg $tempFile /quiet
$cfg = Get-Content $tempFile -Raw
if ($cfg -notmatch 'ClearTextPassword') {
    $cfg = $cfg -replace '\[System Access\]', "[System Access]`r`nClearTextPassword = 0"
} else {
    $cfg = $cfg -replace 'ClearTextPassword\s*=.*', 'ClearTextPassword = 0'
}
$cfg | Set-Content $tempFile -Encoding Unicode
SecEdit.exe /configure /db "$env:TEMP\secpol_temp.sdb" /cfg $tempFile /areas SECURITYPOLICY /quiet
Remove-Item $tempFile -ErrorAction SilentlyContinue
Remove-Item "$env:TEMP\secpol_temp.sdb" -ErrorAction SilentlyContinue
